import{_ as l,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-02-19:: Crimson SeaStor/OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-02-19:: Crimson SeaStor/OSD Weekly Meeting","date":"2019-02-19T00:00:00.000Z","updated":"2019-02-24T00:00:00.000Z","tags":["分布式存储","Ceph","加密协议","性能优化","OSD架构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-02-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-02-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-02-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(n,i,s,_,u,d){return e(),a("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（请在此处填写会议时间）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Nonnie Riddick</li><li>Delius</li><li>Bulai</li><li>Sepia</li><li>Michael</li><li>Greg</li><li>其他相关人员</li></ul><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. 新的帧格式及加密协议</strong>：</p><ul><li>Nonnie Riddick介绍了新的消息协议和帧格式，并讨论了使用加密协议的可行性。</li><li>会议决定在内部测试加密协议，并考虑使用更友好的加密协议。</li></ul><p><strong>2. Ceph 集群状态</strong>：</p><ul><li>Bulai和Sepia报告了Ceph集群的状态，包括心跳支持和消息地址。</li><li>会议讨论了地址错误和连接问题，并决定在Chrome更新中修复这些问题。</li></ul><p><strong>3. 内存存储和恢复机制</strong>：</p><ul><li>Nonnie Riddick提到，在内存存储和恢复机制方面，需要至少部分支持早期激活PG。</li><li>会议讨论了使用队列和优先级来支持请求，并决定进一步研究这个问题。</li></ul><p><strong>4. OSD 架构和任务消费</strong>：</p><ul><li>会议讨论了OSD架构和任务消费模型，包括PG和OSD请求的处理。</li><li>决定在Crimson上进行POC测试，并考虑使用现有的OS层概念和RPG层。</li></ul><p><strong>5. 性能优化和微基准测试</strong>：</p><ul><li>会议讨论了性能优化和微基准测试的重要性，并决定进行更多研究。</li><li>决定在Reactor中进行微基准测试，以评估不同方案的性能。</li></ul><p><strong>6. 社区讨论和反馈</strong>：</p><ul><li>会议鼓励将讨论和想法提交到社区列表，以获得更多反馈。</li><li>决定将设计讨论和问题提交到社区列表，以寻求更多意见和建议。</li></ul><p><strong>7. 其他事项</strong>：</p><ul><li>讨论了Crimson和SISTAR的兼容性，并决定进行更多测试。</li><li>讨论了漫游管理器和性能优化，并决定在后续版本中实现这些功能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>进一步研究加密协议和队列优先级问题。</li><li>在Crimson上进行POC测试，评估不同方案的性能。</li><li>将设计讨论和问题提交到社区列表。</li><li>进行更多微基准测试，以评估性能优化方案。</li><li>实现漫游管理器和性能优化功能。</li></ul><h4 id="关键词" tabindex="-1">关键词： <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词：&quot;">​</a></h4><ul><li>分布式存储</li><li>Ceph</li><li>加密协议</li><li>内存存储</li><li>恢复机制</li><li>OSD架构</li><li>任务消费</li><li>性能优化</li><li>微基准测试</li><li>社区讨论</li></ul>',24)])])}const S=l(r,[["render",o]]);export{h as __pageData,S as default};
